{
  "section": "research",
  "available_sections": [
    {
      "id": "core",
      "description": "Required Python/signal rules and revision lifecycle."
    },
    {
      "id": "research",
      "description": "Required research choices, defaults and explicit inheritance."
    },
    {
      "id": "evidence",
      "description": "Parameter proposals, source claims and saved trading formulas."
    },
    {
      "id": "indicators",
      "description": "Installed indicator catalog and selected API/source reference."
    },
    {
      "id": "example",
      "description": "Complete Python and YAML example to adapt."
    },
    {
      "id": "configuration",
      "description": "Full execution YAML schema and metric settings."
    },
    {
      "id": "runtime",
      "description": "Generated isolation, resource policy and failure recovery."
    }
  ],
  "content": {
    "research_schema": {
      "$defs": {
        "InheritResearchSpec": {
          "additionalProperties": false,
          "description": "Explicitly inherit omitted research choices from one selected fixed revision.",
          "properties": {
            "kind": {
              "const": "inherit_selected_revision",
              "title": "Kind",
              "type": "string"
            },
            "strategy_outline": {
              "minLength": 1,
              "title": "Strategy Outline",
              "type": "string"
            },
            "symbol": {
              "minLength": 1,
              "title": "Symbol",
              "type": "string"
            },
            "start_date": {
              "format": "date-time",
              "title": "Start Date",
              "type": "string"
            },
            "end_date": {
              "format": "date-time",
              "title": "End Date",
              "type": "string"
            },
            "timeframe": {
              "minLength": 1,
              "title": "Timeframe",
              "type": "string"
            },
            "init_cash": {
              "exclusiveMinimum": 0,
              "title": "Init Cash",
              "type": "number"
            },
            "fees": {
              "minimum": 0,
              "title": "Fees",
              "type": "number"
            },
            "slippage": {
              "minimum": 0,
              "title": "Slippage",
              "type": "number"
            },
            "annualization": {
              "anyOf": [
                {
                  "enum": [
                    "market",
                    "unavailable"
                  ],
                  "type": "string"
                },
                {
                  "exclusiveMinimum": 0,
                  "type": "number"
                }
              ],
              "title": "Annualization"
            }
          },
          "required": [
            "kind"
          ],
          "title": "InheritResearchSpec",
          "type": "object"
        },
        "NewResearchSpec": {
          "additionalProperties": false,
          "description": "New research needs all four user choices; only simulation costs have defaults.",
          "properties": {
            "kind": {
              "const": "new",
              "title": "Kind",
              "type": "string"
            },
            "strategy_outline": {
              "minLength": 1,
              "title": "Strategy Outline",
              "type": "string"
            },
            "symbol": {
              "minLength": 1,
              "title": "Symbol",
              "type": "string"
            },
            "start_date": {
              "format": "date-time",
              "title": "Start Date",
              "type": "string"
            },
            "end_date": {
              "format": "date-time",
              "title": "End Date",
              "type": "string"
            },
            "timeframe": {
              "minLength": 1,
              "title": "Timeframe",
              "type": "string"
            },
            "init_cash": {
              "exclusiveMinimum": 0,
              "title": "Init Cash",
              "type": "number"
            },
            "fees": {
              "minimum": 0,
              "title": "Fees",
              "type": "number"
            },
            "slippage": {
              "minimum": 0,
              "title": "Slippage",
              "type": "number"
            },
            "annualization": {
              "anyOf": [
                {
                  "enum": [
                    "market",
                    "unavailable"
                  ],
                  "type": "string"
                },
                {
                  "exclusiveMinimum": 0,
                  "type": "number"
                }
              ],
              "default": "market",
              "title": "Annualization"
            }
          },
          "required": [
            "strategy_outline",
            "symbol",
            "start_date",
            "end_date",
            "timeframe",
            "kind"
          ],
          "title": "NewResearchSpec",
          "type": "object"
        }
      },
      "discriminator": {
        "mapping": {
          "inherit_selected_revision": "#/$defs/InheritResearchSpec",
          "new": "#/$defs/NewResearchSpec"
        },
        "propertyName": "kind"
      },
      "oneOf": [
        {
          "$ref": "#/$defs/NewResearchSpec"
        },
        {
          "$ref": "#/$defs/InheritResearchSpec"
        }
      ]
    },
    "policy": {
      "policy_version": "research-v1",
      "required_inputs": [
        "strategy_outline",
        "symbol",
        "start_date",
        "end_date",
        "timeframe"
      ],
      "simulation_defaults": {
        "init_cash": 10000.0,
        "init_cash_unit": "quote_currency",
        "fees": 0.0006,
        "slippage": 0.0005,
        "description": "Simulation assumptions, not current exchange fees. Explicit valid values take priority; zero costs remain zero. Initial capital applies to signal mode and does not alter volume strategy semantics."
      },
      "annualization": {
        "basis": "observed UTC daily equity returns",
        "crypto_daily_periods_per_year": 365.0,
        "market_policy": "365 is inferred only for a provider whose registered asset classes are exclusively crypto. Mixed providers, including Yahoo, require an explicit positive factor or 'unavailable'.",
        "sampling": "Daily statistics require a declared bar frequency no coarser than one day. A factor does not make weekly/monthly bars into daily observations."
      },
      "provenance": "request/project_default/selected_revision describe configuration origins, not proof of human input. Inheritance requires a selected immutable revision.",
      "data_selection": "Specify data.source or data.requirements.market.source. Providers with market type choices also require an explicit data.market_type."
    },
    "notes": [
      "Before authoring or preparing, obtain the user's strategy idea, instrument, date interval and candle timeframe. A vague trading idea is sufficient; missing choices require clarification, not values copied from examples or a bundled configuration.",
      "research owns market/date/capital/cost/annualization choices. The YAML supplies strategy class/parameters, explicit data source, features, execution controls and validation. When saving, duplicate research fields in YAML must agree; the backend materializes the complete immutable base configuration before program checks.",
      "Omit unspecified capital and costs to use the maintained simulation policy. Preserve the user's explicit valid values, including zero. Do not supply guessed values and describe them as user instructions.",
      "inherit_selected_revision is an explicit choice to reuse one identified generated revision; it is not a missing-value fallback. Supply that exact revision_id when preparing, or expected_revision_id when repairing. Bundled sample dates cannot supply missing choices.",
      "Research periods select candle timestamps with start_date <= timestamp <= end_date, including both endpoints when matching candles exist. Dates without timezone are interpreted as UTC; explicit offsets convert to UTC. Date-only values mean 00:00:00 UTC, not the whole final day. Review these exact resolved bounds with the user. No history is read before approval, so actual available bars and gaps are still unverified.",
      "Use annualization='market' only when a supported market policy applies. Otherwise propose and disclose a justified positive daily factor, or obtain an explicit choice to proceed with annualization unavailable. Do not apply a universal stock-market day count.",
      "Source labels describe what the backend resolved from this request, the project policy or a selected revision. They do not establish that a human supplied or approved those choices."
    ]
  }
}

{
  "section": "configuration",
  "available_sections": [
    {
      "id": "core",
      "description": "Required Python/signal rules and revision lifecycle."
    },
    {
      "id": "research",
      "description": "Required research choices, defaults and explicit inheritance."
    },
    {
      "id": "evidence",
      "description": "Parameter proposals, source claims and saved trading formulas."
    },
    {
      "id": "indicators",
      "description": "Installed indicator catalog and selected API/source reference."
    },
    {
      "id": "example",
      "description": "Complete Python and YAML example to adapt."
    },
    {
      "id": "configuration",
      "description": "Full execution YAML schema and metric settings."
    },
    {
      "id": "runtime",
      "description": "Generated isolation, resource policy and failure recovery."
    }
  ],
  "content": {
    "config_schema": {
      "$defs": {
        "AutomaticWalkForwardConfig": {
          "additionalProperties": false,
          "description": "Rolling or expanding windows computed from the available row count.",
          "properties": {
            "target_metric": {
              "default": "sharpe_ratio",
              "description": "Fold log/summary metric; does not configure strategy training.",
              "title": "Target Metric",
              "type": "string"
            },
            "label_horizon": {
              "default": 0,
              "description": "Forward label bars; zero disables the fold leakage audit.",
              "minimum": 0,
              "title": "Label Horizon",
              "type": "integer"
            },
            "mode": {
              "const": "automatic",
              "title": "Mode",
              "type": "string"
            },
            "n_splits": {
              "default": 1,
              "minimum": 1,
              "title": "N Splits",
              "type": "integer"
            },
            "train_ratio": {
              "default": 0.8,
              "exclusiveMaximum": 1,
              "exclusiveMinimum": 0,
              "title": "Train Ratio",
              "type": "number"
            },
            "expanding": {
              "default": false,
              "title": "Expanding",
              "type": "boolean"
            }
          },
          "required": [
            "mode"
          ],
          "title": "AutomaticWalkForwardConfig",
          "type": "object"
        },
        "BacktestConfig": {
          "additionalProperties": false,
          "description": "Backtest execution configuration.",
          "properties": {
            "symbol": {
              "title": "Symbol",
              "type": "string"
            },
            "timeframe": {
              "title": "Timeframe",
              "type": "string"
            },
            "start_date": {
              "format": "date-time",
              "title": "Start Date",
              "type": "string"
            },
            "end_date": {
              "format": "date-time",
              "title": "End Date",
              "type": "string"
            },
            "init_cash": {
              "anyOf": [
                {
                  "exclusiveMinimum": 0,
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Init Cash"
            },
            "fees": {
              "default": 0.0006,
              "title": "Fees",
              "type": "number"
            },
            "slippage": {
              "default": 0.0005,
              "title": "Slippage",
              "type": "number"
            },
            "position_size": {
              "anyOf": [
                {
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Position Size"
            },
            "stop_loss": {
              "anyOf": [
                {
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Stop Loss"
            },
            "take_profit": {
              "anyOf": [
                {
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Take Profit"
            },
            "signal_as_position": {
              "default": false,
              "description": "Volume mode only: true makes signal=0 close an existing position; false retains it while preventing new entries. Signal mode always uses position states (1 long, -1 short, 0 flat) and ignores this flag. In both modes -1 selects short, not a sell-only exit.",
              "title": "Signal As Position",
              "type": "boolean"
            },
            "re_entry_after_sl": {
              "default": true,
              "title": "Re Entry After Sl",
              "type": "boolean"
            },
            "mode": {
              "default": "signal",
              "enum": [
                "signal",
                "volume"
              ],
              "title": "Mode",
              "type": "string"
            },
            "monthly_max_loss": {
              "default": 1500.0,
              "description": "Volume mode only; requires timestamps. Quote-currency loss limit for each UTC calendar month. Compare cumulative P&L equity with the previous observed month's last close equity (zero in the first month). Missing months are not filled; gaps belong to the next observed month. Count current-month costs and unrealised P&L changes, not prior-month P&L or entry costs again. Trade records retain whole-trade P&L and costs. Check after stop exits before re-entry and after ordinary trading at close. Reaching the loss limit closes any remaining position at close and pauses until the next observed month; exit costs may exceed the limit.",
              "title": "Monthly Max Loss",
              "type": "number"
            },
            "periods_per_year": {
              "anyOf": [
                {
                  "exclusiveMinimum": 0,
                  "type": "number"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Periods Per Year"
            },
            "risk_free_rate": {
              "default": 0.0,
              "exclusiveMinimum": -1,
              "title": "Risk Free Rate",
              "type": "number"
            },
            "required_return": {
              "default": 0.0,
              "exclusiveMinimum": -1,
              "title": "Required Return",
              "type": "number"
            }
          },
          "required": [
            "symbol",
            "timeframe",
            "start_date",
            "end_date"
          ],
          "title": "BacktestConfig",
          "type": "object"
        },
        "ExplicitWalkForwardConfig": {
          "additionalProperties": false,
          "description": "One training/test pair, with inclusive nonoverlapping UTC calendar days.",
          "properties": {
            "target_metric": {
              "default": "sharpe_ratio",
              "description": "Fold log/summary metric; does not configure strategy training.",
              "title": "Target Metric",
              "type": "string"
            },
            "label_horizon": {
              "default": 0,
              "description": "Forward label bars; zero disables the fold leakage audit.",
              "minimum": 0,
              "title": "Label Horizon",
              "type": "integer"
            },
            "mode": {
              "const": "explicit",
              "title": "Mode",
              "type": "string"
            },
            "train_start": {
              "format": "date-time",
              "title": "Train Start",
              "type": "string"
            },
            "train_end": {
              "format": "date-time",
              "title": "Train End",
              "type": "string"
            },
            "test_start": {
              "format": "date-time",
              "title": "Test Start",
              "type": "string"
            },
            "test_end": {
              "format": "date-time",
              "title": "Test End",
              "type": "string"
            }
          },
          "required": [
            "mode",
            "train_start",
            "train_end",
            "test_start",
            "test_end"
          ],
          "title": "ExplicitWalkForwardConfig",
          "type": "object"
        },
        "ParallelConfig": {
          "additionalProperties": false,
          "description": "Parallel execution configuration.",
          "properties": {
            "reserve_cores": {
              "default": 2,
              "title": "Reserve Cores",
              "type": "integer"
            },
            "safety_factor": {
              "default": 0.6,
              "title": "Safety Factor",
              "type": "number"
            },
            "overhead_multiplier": {
              "default": 3.0,
              "exclusiveMinimum": 0,
              "title": "Overhead Multiplier",
              "type": "number"
            }
          },
          "title": "ParallelConfig",
          "type": "object"
        },
        "PurgedWalkForwardConfig": {
          "additionalProperties": false,
          "description": "Anchored expanding windows with label purge and an optional extra embargo.",
          "properties": {
            "target_metric": {
              "default": "sharpe_ratio",
              "description": "Fold log/summary metric; does not configure strategy training.",
              "title": "Target Metric",
              "type": "string"
            },
            "label_horizon": {
              "description": "Required positive forward label horizon in bars.",
              "exclusiveMinimum": 0,
              "title": "Label Horizon",
              "type": "integer"
            },
            "mode": {
              "const": "purged",
              "title": "Mode",
              "type": "string"
            },
            "n_splits": {
              "default": 1,
              "minimum": 1,
              "title": "N Splits",
              "type": "integer"
            },
            "embargo_bars": {
              "default": 0,
              "minimum": 0,
              "title": "Embargo Bars",
              "type": "integer"
            }
          },
          "required": [
            "label_horizon",
            "mode"
          ],
          "title": "PurgedWalkForwardConfig",
          "type": "object"
        },
        "ResearchMetadata": {
          "additionalProperties": false,
          "description": "Origins of resolved fields, never a proof that a human supplied the input.",
          "properties": {
            "schema_version": {
              "const": 1,
              "default": 1,
              "title": "Schema Version",
              "type": "integer"
            },
            "policy_version": {
              "minLength": 1,
              "title": "Policy Version",
              "type": "string"
            },
            "strategy_outline": {
              "minLength": 1,
              "title": "Strategy Outline",
              "type": "string"
            },
            "field_sources": {
              "additionalProperties": {
                "enum": [
                  "request",
                  "project_default",
                  "selected_revision"
                ],
                "type": "string"
              },
              "title": "Field Sources",
              "type": "object"
            },
            "selected_revision": {
              "anyOf": [
                {
                  "$ref": "#/$defs/ResearchRevisionIdentity"
                },
                {
                  "type": "null"
                }
              ],
              "default": null
            },
            "annualization_reason": {
              "minLength": 1,
              "title": "Annualization Reason",
              "type": "string"
            }
          },
          "required": [
            "policy_version",
            "strategy_outline",
            "field_sources",
            "annualization_reason"
          ],
          "title": "ResearchMetadata",
          "type": "object"
        },
        "ResearchRevisionIdentity": {
          "additionalProperties": false,
          "description": "Identity of the immutable YAML used for explicit inheritance.",
          "properties": {
            "strategy_id": {
              "minLength": 1,
              "title": "Strategy Id",
              "type": "string"
            },
            "revision_id": {
              "minLength": 1,
              "title": "Revision Id",
              "type": "string"
            },
            "config_hash": {
              "anyOf": [
                {
                  "pattern": "^[0-9a-f]{64}$",
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Config Hash"
            }
          },
          "required": [
            "strategy_id",
            "revision_id"
          ],
          "title": "ResearchRevisionIdentity",
          "type": "object"
        },
        "RunDataConfig": {
          "additionalProperties": false,
          "description": "Data settings whose environment-dependent defaults resolve at submission.",
          "properties": {
            "source": {
              "default": "binance_vision",
              "title": "Source",
              "type": "string"
            },
            "market_type": {
              "default": "futures/um",
              "title": "Market Type",
              "type": "string"
            },
            "raw_dir": {
              "default": "workspace/data/raw",
              "title": "Raw Dir",
              "type": "string"
            },
            "processed_dir": {
              "default": "workspace/data/processed",
              "title": "Processed Dir",
              "type": "string"
            },
            "requirements": {
              "anyOf": [
                {
                  "$ref": "#/$defs/RunDataRequirement"
                },
                {
                  "type": "null"
                }
              ],
              "default": null
            }
          },
          "title": "RunDataConfig",
          "type": "object"
        },
        "RunDataRequirement": {
          "additionalProperties": false,
          "description": "Strict requirements within a strategy execution configuration.",
          "properties": {
            "market": {
              "$ref": "#/$defs/RunMarketDataSpec"
            },
            "features": {
              "items": {
                "$ref": "#/$defs/RunFeatureSpec"
              },
              "title": "Features",
              "type": "array"
            }
          },
          "required": [
            "market"
          ],
          "title": "RunDataRequirement",
          "type": "object"
        },
        "RunFeatureSpec": {
          "additionalProperties": false,
          "description": "Reject misspelled feature requirement fields before execution.",
          "properties": {
            "type": {
              "enum": [
                "dvol",
                "funding_rate",
                "custom"
              ],
              "title": "Type",
              "type": "string"
            },
            "source": {
              "title": "Source",
              "type": "string"
            },
            "column": {
              "title": "Column",
              "type": "string"
            },
            "path": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Path"
            },
            "raw_path": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Raw Path"
            }
          },
          "required": [
            "type",
            "source",
            "column"
          ],
          "title": "RunFeatureSpec",
          "type": "object"
        },
        "RunMarketDataSpec": {
          "additionalProperties": false,
          "description": "Reject misspelled market requirement fields before execution.",
          "properties": {
            "source": {
              "default": "binance_vision",
              "title": "Source",
              "type": "string"
            },
            "symbol": {
              "title": "Symbol",
              "type": "string"
            },
            "timeframe": {
              "title": "Timeframe",
              "type": "string"
            }
          },
          "required": [
            "symbol",
            "timeframe"
          ],
          "title": "RunMarketDataSpec",
          "type": "object"
        },
        "StrategyRunConfig": {
          "additionalProperties": false,
          "description": "Known strategy metadata, with explicit dynamic constructor parameters.",
          "properties": {
            "id": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Id"
            },
            "revision_id": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Revision Id"
            },
            "version": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Version"
            },
            "class_name": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Class Name"
            },
            "description": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Description"
            },
            "display_name": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Display Name"
            },
            "training_requirement": {
              "$ref": "#/$defs/TrainingRequirement",
              "default": "unknown",
              "description": "Bundled catalog declaration, not an execution override or model state. Generated strategy capabilities remain unknown."
            },
            "source_path": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Source Path"
            },
            "source_hash": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Source Hash"
            },
            "parameters": {
              "additionalProperties": true,
              "title": "Parameters",
              "type": "object"
            },
            "fit": {
              "anyOf": [
                {
                  "additionalProperties": true,
                  "type": "object"
                },
                {
                  "type": "null"
                }
              ],
              "default": null,
              "title": "Fit"
            }
          },
          "title": "StrategyRunConfig",
          "type": "object"
        },
        "TrainingRequirement": {
          "enum": [
            "required",
            "optional",
            "unknown"
          ],
          "type": "string"
        },
        "WalkForwardConfig": {
          "discriminator": {
            "mapping": {
